#!/usr/bin/env python3
"""Баннер «Подпишись в Telegram» над плеером: неон с мерцанием как у неисправной вывески, крупный шрифт на компьютере,
показывается на ВСЕХ ширинах экрана (раньше пропадал на узких экранах). Идемпотентно.
Метка версии: /*tgneon3*/. Старые версии (/*tgneon*/, /*tgneon2*/) удаляются целиком, новый блок кладётся в конец <style>,
где лежат правила баннера (вне @media)."""
import sys, os, glob
ROOT = os.path.abspath(sys.argv[1] if len(sys.argv) > 1 else '.')
OLD = ['/*tgneon*/@media(min-width:1025px){.tg-banner-desk{border:2px solid #2aa9e0;background:linear-gradient(135deg,#071a33,#06283f);animation:tgNeon 1.6s ease-in-out infinite}.tg-banner-desk-icon{box-shadow:0 0 12px #229ED9;animation:tgNeonIcon 1.6s ease-in-out infinite}.tg-banner-desk-text b{text-shadow:0 0 8px rgba(63,195,255,.9)}.tg-banner-desk-arrow{color:#7fdcff;opacity:1;animation:tgNeonArrow 1.6s ease-in-out infinite}}@keyframes tgNeon{0%,100%{box-shadow:0 0 4px rgba(63,195,255,.5),0 0 12px rgba(34,158,217,.35),inset 0 0 6px rgba(63,195,255,.15);border-color:#2aa9e0}50%{box-shadow:0 0 8px #3fc3ff,0 0 24px rgba(34,158,217,.8),0 0 44px rgba(34,158,217,.45),inset 0 0 14px rgba(63,195,255,.35);border-color:#7fe0ff}}@keyframes tgNeonIcon{0%,100%{transform:scale(1)}50%{transform:scale(1.12)}}@keyframes tgNeonArrow{0%,100%{transform:translateX(0)}50%{transform:translateX(4px)}}@media(prefers-reduced-motion:reduce){.tg-banner-desk,.tg-banner-desk-icon,.tg-banner-desk-arrow{animation:none}}',
       '/*tgneon2*/@media(min-width:1025px){.tg-banner-desk{padding:14px 20px;gap:14px;border:2px solid #7fe0ff;background:linear-gradient(135deg,#071a33,#06283f);box-shadow:0 0 8px #3fc3ff,0 0 24px rgba(34,158,217,.8),0 0 44px rgba(34,158,217,.45),inset 0 0 14px rgba(63,195,255,.35);animation:tgNeon 4.2s step-end infinite}.tg-banner-desk-icon{width:40px;height:40px;box-shadow:0 0 14px #229ED9;animation:tgNeonIco 4.2s step-end infinite}.tg-banner-desk-icon svg{width:22px;height:22px}.tg-banner-desk-text{font-size:17px;line-height:1.3}.tg-banner-desk-text b{font-size:20px;letter-spacing:.2px;color:#fff;text-shadow:0 0 6px #fff,0 0 12px #3fc3ff,0 0 24px #229ED9;animation:tgNeonTxt 4.2s step-end infinite}.tg-banner-desk-arrow{font-size:24px;color:#9fe6ff;opacity:1;text-shadow:0 0 10px #3fc3ff;animation:tgNeonTxt 4.2s step-end infinite}}@keyframes tgNeon{0%{border-color:#7fe0ff;box-shadow:0 0 8px #3fc3ff,0 0 24px rgba(34,158,217,.8),0 0 44px rgba(34,158,217,.45),inset 0 0 14px rgba(63,195,255,.35)}3%{border-color:#15506d;box-shadow:0 0 0 transparent,inset 0 0 0 transparent}5%{border-color:#7fe0ff;box-shadow:0 0 8px #3fc3ff,0 0 24px rgba(34,158,217,.8),0 0 44px rgba(34,158,217,.45),inset 0 0 14px rgba(63,195,255,.35)}7%{border-color:#15506d;box-shadow:0 0 0 transparent,inset 0 0 0 transparent}8.5%{border-color:#7fe0ff;box-shadow:0 0 8px #3fc3ff,0 0 24px rgba(34,158,217,.8),0 0 44px rgba(34,158,217,.45),inset 0 0 14px rgba(63,195,255,.35)}10%{border-color:#15506d;box-shadow:0 0 0 transparent,inset 0 0 0 transparent}11%{border-color:#7fe0ff;box-shadow:0 0 8px #3fc3ff,0 0 24px rgba(34,158,217,.8),0 0 44px rgba(34,158,217,.45),inset 0 0 14px rgba(63,195,255,.35)}52%{border-color:#15506d;box-shadow:0 0 0 transparent,inset 0 0 0 transparent}54%{border-color:#7fe0ff;box-shadow:0 0 8px #3fc3ff,0 0 24px rgba(34,158,217,.8),0 0 44px rgba(34,158,217,.45),inset 0 0 14px rgba(63,195,255,.35)}55.5%{border-color:#15506d;box-shadow:0 0 0 transparent,inset 0 0 0 transparent}57%{border-color:#7fe0ff;box-shadow:0 0 8px #3fc3ff,0 0 24px rgba(34,158,217,.8),0 0 44px rgba(34,158,217,.45),inset 0 0 14px rgba(63,195,255,.35)}58%{border-color:#15506d;box-shadow:0 0 0 transparent,inset 0 0 0 transparent}59%{border-color:#7fe0ff;box-shadow:0 0 8px #3fc3ff,0 0 24px rgba(34,158,217,.8),0 0 44px rgba(34,158,217,.45),inset 0 0 14px rgba(63,195,255,.35)}100%{border-color:#7fe0ff;box-shadow:0 0 8px #3fc3ff,0 0 24px rgba(34,158,217,.8),0 0 44px rgba(34,158,217,.45),inset 0 0 14px rgba(63,195,255,.35)}}@keyframes tgNeonIco{0%{box-shadow:0 0 14px #229ED9;filter:none}3%{box-shadow:none;filter:brightness(.55)}5%{box-shadow:0 0 14px #229ED9;filter:none}7%{box-shadow:none;filter:brightness(.55)}8.5%{box-shadow:0 0 14px #229ED9;filter:none}10%{box-shadow:none;filter:brightness(.55)}11%{box-shadow:0 0 14px #229ED9;filter:none}52%{box-shadow:none;filter:brightness(.55)}54%{box-shadow:0 0 14px #229ED9;filter:none}55.5%{box-shadow:none;filter:brightness(.55)}57%{box-shadow:0 0 14px #229ED9;filter:none}58%{box-shadow:none;filter:brightness(.55)}59%{box-shadow:0 0 14px #229ED9;filter:none}100%{box-shadow:0 0 14px #229ED9;filter:none}}@keyframes tgNeonTxt{0%{color:#fff;text-shadow:0 0 6px #fff,0 0 12px #3fc3ff,0 0 24px #229ED9}3%{color:#5d7f93;text-shadow:none}5%{color:#fff;text-shadow:0 0 6px #fff,0 0 12px #3fc3ff,0 0 24px #229ED9}7%{color:#5d7f93;text-shadow:none}8.5%{color:#fff;text-shadow:0 0 6px #fff,0 0 12px #3fc3ff,0 0 24px #229ED9}10%{color:#5d7f93;text-shadow:none}11%{color:#fff;text-shadow:0 0 6px #fff,0 0 12px #3fc3ff,0 0 24px #229ED9}52%{color:#5d7f93;text-shadow:none}54%{color:#fff;text-shadow:0 0 6px #fff,0 0 12px #3fc3ff,0 0 24px #229ED9}55.5%{color:#5d7f93;text-shadow:none}57%{color:#fff;text-shadow:0 0 6px #fff,0 0 12px #3fc3ff,0 0 24px #229ED9}58%{color:#5d7f93;text-shadow:none}59%{color:#fff;text-shadow:0 0 6px #fff,0 0 12px #3fc3ff,0 0 24px #229ED9}100%{color:#fff;text-shadow:0 0 6px #fff,0 0 12px #3fc3ff,0 0 24px #229ED9}}@media(prefers-reduced-motion:reduce){.tg-banner-desk,.tg-banner-desk-icon,.tg-banner-desk-text b,.tg-banner-desk-arrow{animation:none}}']
FLICKER = [(0, 1), (3, 0), (5, 1), (7, 0), (8.5, 1), (10, 0), (11, 1), (52, 0), (54, 1), (55.5, 0), (57, 1), (58, 0), (59, 1), (100, 1)]
def kf(name, on, off):
    return '@keyframes %s{%s}' % (name, ''.join('%s%%{%s}' % (('%g' % t), on if v else off) for t, v in FLICKER))
ON_BOX = 'border-color:#7fe0ff;box-shadow:0 0 8px #3fc3ff,0 0 24px rgba(34,158,217,.8),0 0 44px rgba(34,158,217,.45),inset 0 0 14px rgba(63,195,255,.35)'
CSS = (
 '/*tgneon3*/'
 '.tg-banner-desk{display:flex;align-items:center;gap:10px;padding:10px 14px;border:2px solid #7fe0ff;border-radius:var(--radius,12px);'
 'background:linear-gradient(135deg,#071a33,#06283f);text-decoration:none;color:#fff;box-shadow:0 0 8px #3fc3ff,0 0 24px rgba(34,158,217,.8),0 0 44px rgba(34,158,217,.45),inset 0 0 14px rgba(63,195,255,.35);animation:tgNeon 4.2s step-end infinite}'
 '.tg-banner-desk-icon{width:32px;height:32px;background:#229ED9;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0;box-shadow:0 0 14px #229ED9;animation:tgNeonIco 4.2s step-end infinite}'
 '.tg-banner-desk-icon svg{width:18px;height:18px}'
 '.tg-banner-desk-text{flex:1;min-width:0;font-size:14px;line-height:1.3;color:rgba(255,255,255,.9)}'
 '.tg-banner-desk-text b{font-size:16px;color:#fff;text-shadow:0 0 6px #fff,0 0 12px #3fc3ff,0 0 24px #229ED9;animation:tgNeonTxt 4.2s step-end infinite}'
 '.tg-banner-desk-arrow{font-size:18px;color:#9fe6ff;opacity:1;flex-shrink:0;text-shadow:0 0 10px #3fc3ff;animation:tgNeonTxt 4.2s step-end infinite}'
 '@media(min-width:1025px){.tg-banner-desk{padding:14px 20px;gap:14px}.tg-banner-desk-icon{width:40px;height:40px}.tg-banner-desk-icon svg{width:22px;height:22px}'
 '.tg-banner-desk-text{font-size:17px}.tg-banner-desk-text b{font-size:20px;letter-spacing:.2px}.tg-banner-desk-arrow{font-size:24px}}'
 + kf('tgNeon', ON_BOX, 'border-color:#15506d;box-shadow:0 0 0 transparent,inset 0 0 0 transparent')
 + kf('tgNeonIco', 'box-shadow:0 0 14px #229ED9;filter:none', 'box-shadow:none;filter:brightness(.55)')
 + kf('tgNeonTxt', 'color:#fff;text-shadow:0 0 6px #fff,0 0 12px #3fc3ff,0 0 24px #229ED9', 'color:#5d7f93;text-shadow:none')
 + '@media(prefers-reduced-motion:reduce){.tg-banner-desk,.tg-banner-desk-icon,.tg-banner-desk-text b,.tg-banner-desk-arrow{animation:none}}'
)
n = 0
for f in glob.glob(os.path.join(ROOT, '**/*.html'), recursive=True):
    s = open(f, encoding='utf-8').read()
    if 'class="tg-banner-desk"' not in s or '/*tgneon3*/' in s: continue
    for o in OLD: s = s.replace(o, '')
    i = s.find('.tg-banner-desk')
    k = s.find('</style>', i)
    if i < 0 or k < 0: print('нет <style>:', os.path.relpath(f, ROOT)); continue
    open(f, 'w', encoding='utf-8').write(s[:k] + CSS + s[k:]); n += 1
print('tgneon3:', n, 'страниц изменено')
